from pathlib import Path
p=Path('src/conv.rs')
s=p.read_text()
old='''    #[inline]\n    fn unify<const RIGID: bool>(&mut self, depth: u32, x: V<'t>, y: V<'t>) -> bool {\n        let x = self.force_thunk(depth, x);\n        let y = self.force_thunk(depth, y);\n        if std::ptr::eq(x, y) {\n            return true;\n        }\n        self.unify_general::<RIGID>(depth, x, y)\n    }\n'''
new='''    #[inline]\n    fn unify<const RIGID: bool>(&mut self, depth: u32, x: V<'t>, y: V<'t>) -> bool {\n        use std::sync::atomic::{AtomicU64, Ordering};\n        static TOTAL: AtomicU64 = AtomicU64::new(0);\n        static RAW_PTR: AtomicU64 = AtomicU64::new(0);\n        static POST_FORCE_PTR: AtomicU64 = AtomicU64::new(0);\n        let n = TOTAL.fetch_add(1, Ordering::Relaxed) + 1;\n        if std::ptr::eq(x, y) {\n            RAW_PTR.fetch_add(1, Ordering::Relaxed);\n            if n % 1_000_000 == 0 {\n                eprintln!(\"MSI_PREFORCE_PTR total={} raw={} post={}\", n, RAW_PTR.load(Ordering::Relaxed), POST_FORCE_PTR.load(Ordering::Relaxed));\n            }\n            return true;\n        }\n        let x = self.force_thunk(depth, x);\n        let y = self.force_thunk(depth, y);\n        if std::ptr::eq(x, y) {\n            POST_FORCE_PTR.fetch_add(1, Ordering::Relaxed);\n            if n % 1_000_000 == 0 {\n                eprintln!(\"MSI_PREFORCE_PTR total={} raw={} post={}\", n, RAW_PTR.load(Ordering::Relaxed), POST_FORCE_PTR.load(Ordering::Relaxed));\n            }\n            return true;\n        }\n        if n % 1_000_000 == 0 {\n            eprintln!(\"MSI_PREFORCE_PTR total={} raw={} post={}\", n, RAW_PTR.load(Ordering::Relaxed), POST_FORCE_PTR.load(Ordering::Relaxed));\n        }\n        self.unify_general::<RIGID>(depth, x, y)\n    }\n'''
if old not in s: raise SystemExit('target not found')
p.write_text(s.replace(old,new,1))
print('applied MSI pre-force pointer v14')
